  function clearLogoWaveTimers() {
    logoWaveTimers.forEach((timer) => window.clearTimeout(timer));
    logoWaveTimers = [];
    logoWaveRects.forEach((rect) => {
      const state = getLogoRectWaveState(rect);
      state.wave.clear();
      state.tail.clear();
      state.pressed.clear();
      syncLogoRectWaveClasses(rect);
    });
  }

  function queueLogoWaveTimer(callback, delay) {
    const timer = window.setTimeout(
      () => {
        logoWaveTimers = logoWaveTimers.filter(
          (activeTimer) => activeTimer !== timer,
        );
        callback();
      },
      Math.max(0, delay),
    );

    logoWaveTimers.push(timer);
  }

  function getLogoRectWaveState(rect) {
    let state = logoRectWaveStates.get(rect);

    if (!state) {
      state = {
        wave: new Set(),
        tail: new Set(),
        pressed: new Set(),
      };
      logoRectWaveStates.set(rect, state);
      logoWaveRects.add(rect);
    }

    return state;
  }

  function syncLogoRectWaveClasses(rect) {
    const state = getLogoRectWaveState(rect);
    rect.classList.toggle("is-logo-wave", state.wave.size > 0);
    rect.classList.toggle(
      "is-logo-wave-tail",
      state.tail.size > 0 && state.wave.size === 0,
    );
    rect.classList.toggle("is-logo-pressed", state.pressed.size > 0);
  }

  function setLogoRectWaveState(rect, type, waveId, active) {
    const state = getLogoRectWaveState(rect);

    if (active) {
      state[type].add(waveId);
    } else {
      state[type].delete(waveId);
    }

    syncLogoRectWaveClasses(rect);
  }

  function getSvgRectCenter(rect) {
    const x = Number(rect.getAttribute("x") || 0);
    const y = Number(rect.getAttribute("y") || 0);
    const width = Number(rect.getAttribute("width") || 0);
    const height = Number(rect.getAttribute("height") || 0);

    return {
      x: x + width / 2,
      y: y + height / 2,
    };
  }

  function runLogoRectWave(svg, sourceRect) {
    const rects = [...svg.querySelectorAll(".hero-logo-shapes rect")];
    const sourceCenter = getSvgRectCenter(sourceRect);
    const waveCount = Math.max(1, Math.round(logoClickSettings.waveCount || 1));
    const waveGap = Math.max(0, logoClickSettings.waveGap || 0);

    for (let waveIndex = 0; waveIndex < waveCount; waveIndex += 1) {
      const waveId = ++logoWaveInstanceId;
      const waveOffset = waveIndex * waveGap;

      rects.forEach((rect) => {
        const center = getSvgRectCenter(rect);
        const distance = Math.hypot(
          center.x - sourceCenter.x,
          center.y - sourceCenter.y,
        );
        const delay =
          waveOffset + Math.round(distance * logoClickSettings.waveSpread);
        const hold = logoClickSettings.waveHold;
        const tailHold = logoClickSettings.tailHold;

        queueLogoWaveTimer(() => {
          setLogoRectWaveState(rect, "tail", waveId, false);
          setLogoRectWaveState(rect, "wave", waveId, true);

          if (rect === sourceRect) {
            setLogoRectWaveState(rect, "pressed", waveId, true);
          }
        }, delay);

        queueLogoWaveTimer(() => {
          setLogoRectWaveState(rect, "wave", waveId, false);
          setLogoRectWaveState(rect, "pressed", waveId, false);
          setLogoRectWaveState(rect, "tail", waveId, true);
        }, delay + hold);

        queueLogoWaveTimer(
          () => {
            setLogoRectWaveState(rect, "tail", waveId, false);
          },
          delay + hold + tailHold,
        );
      });
    }
  }

  function setupLogoRectInteraction(svg) {
    [...svg.querySelectorAll(".hero-logo-shapes rect")].forEach(
      (rect, index) => {
        rect.dataset.logoRect = String(index);
        rect.addEventListener("click", (event) => {
          event.stopPropagation();
          runLogoRectWave(svg, rect);
        });
      },
    );
  }

  function normalizeLogoSvg(svg) {
    svg.setAttribute("preserveAspectRatio", "none");
    svg.classList.add("hero-logo-inline-svg");

    const mask = svg.querySelector("mask");
    const maskedFill = svg.querySelector("g[mask]");

    if (!mask) {
      return;
    }

    const shapes = document.createElementNS("http://www.w3.org/2000/svg", "g");
    shapes.classList.add("hero-logo-shapes");
    const pathsLayer = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "g",
    );
    pathsLayer.classList.add("hero-logo-line-layer");
    const rectsLayer = document.createElementNS(
      "http://www.w3.org/2000/svg",
      "g",
    );
    rectsLayer.classList.add("hero-logo-rect-layer");

    [...mask.children].forEach((shape) => {
      const clone = shape.cloneNode(true);
      clone.removeAttribute("style");
      clone.removeAttribute("mask");

      if (clone.tagName.toLowerCase() === "rect") {
        clone.setAttribute("fill", "#32323C");
      }

      if (clone.tagName.toLowerCase() === "path") {
        clone.setAttribute("fill", "none");
        clone.setAttribute("stroke", "#32323C");
        clone.setAttribute("stroke-linejoin", "miter");
      }

      if (clone.tagName.toLowerCase() === "path") {
        pathsLayer.appendChild(clone);
      } else {
        rectsLayer.appendChild(clone);
      }
    });

    shapes.append(pathsLayer, rectsLayer);
    maskedFill?.remove();
    mask.remove();
    svg.appendChild(shapes);
    setupLogoRectInteraction(svg);
  }

  async function loadLogoSvg() {
    if (!logoSvgHosts.length) {
      return;
    }

    try {
      const svgText =
        window.DATABRICKS_EXPORT_ASSETS?.logoSvg ||
        (await (async () => {
          const response = await fetch("./assets/databricks-logo.svg");
          if (!response.ok) {
            throw new Error(`Logo SVG failed with ${response.status}`);
          }

          return response.text();
        })());

      logoSvgHosts.forEach((host) => {
        host.innerHTML = svgText;
        const svg = host.querySelector("svg");
        if (svg) {
          normalizeLogoSvg(svg);
        }
      });
    } catch (error) {
      console.warn("Could not load inline logo SVG", error);
    }
  }

  function setLogoReveal(percent, shift = 0) {
    root.style.setProperty("--logo-reveal", `${percent}%`);
    root.style.setProperty("--logo-shift", `${shift}px`);
  }

  function setLogoBlockOpacity(value) {
    root.style.setProperty(
      "--logo-block-opacity",
      Math.max(0, Math.min(1, Number(value) || 0)).toFixed(3),
    );
  }

  async function waitLogoRevealHold(duration, token, respectPause) {
    if (respectPause) {
      await wait(duration, token);
      return;
    }

    let remaining = duration;

    while (remaining > 0) {
      if (token !== runId) {
        throw new Error("Animation cancelled");
      }

      const chunk = Math.min(remaining, 50);
      const startedAt = performance.now();
      await rawWait(chunk);
      remaining -= performance.now() - startedAt;
    }
  }

  async function animateLogoBlockOpacity(
    token,
    { respectPause = false, revealRunId = ++logoRunId } = {},
  ) {
    const localLogoRunId = revealRunId;
    const logoSettings = stateLogoSettings[1];
    const opacityDuration = Math.max(
      0,
      Number(logoSettings.opacityDuration ?? 420),
    );

    if (opacityDuration <= 0) {
      setLogoBlockOpacity(1);
      return;
    }

    const steps = Math.max(1, Math.round(opacityDuration / 34));
    const stepHold = opacityDuration / steps;

    for (let step = 0; step <= steps; step += 1) {
      if (token !== runId || localLogoRunId !== logoRunId) {
        return;
      }

      const progress = step / steps;
      setLogoBlockOpacity(progress);

      if (step < steps) {
        await waitLogoRevealHold(stepHold, token, respectPause);
      }
    }

    setLogoBlockOpacity(1);
  }

  async function animateLogoReveal(
    token,
    { respectPause = false, revealRunId = ++logoRunId } = {},
  ) {
    const localLogoRunId = revealRunId;
    const logoSettings = stateLogoSettings[1];
    const revealDuration = Math.max(
      0,
      Number(logoSettings.revealDuration || 0),
    );
    const stutter = Math.max(0, Number(logoSettings.stutter || 0));
    const revealSteps = [
      [0, 0, 80],
      [4, 0, 120],
      [8, -1, 55],
      [7, 1, 45],
      [13, 0, 90],
      [19, 0, 70],
      [24, -1, 120],
      [31, 1, 55],
      [30, 0, 45],
      [38, 0, 105],
      [47, -1, 70],
      [55, 0, 130],
      [63, 1, 50],
      [62, 0, 45],
      [72, 0, 90],
      [81, -1, 70],
      [90, 0, 110],
      [96, 1, 55],
      [100, 0, 0],
    ];
    const totalHold = revealSteps.reduce((sum, step) => sum + step[2], 0);
    const durationScale = revealDuration / totalHold;
    const stutterMix = Math.min(1.8, stutter / 6);
    let highestReveal = 0;

    heroLogoReveal.classList.add("is-revealing");

    try {
      if (revealDuration <= 0) {
        setLogoReveal(100, 0);
        return;
      }

      for (const [percent, shift, hold] of revealSteps) {
        if (token !== runId || localLogoRunId !== logoRunId) {
          return;
        }

        highestReveal = Math.max(highestReveal, percent);
        const mixedPercent =
          highestReveal + (percent - highestReveal) * stutterMix;
        const mixedShift = shift * stutterMix * 2;
        setLogoReveal(mixedPercent, mixedShift);
        await waitLogoRevealHold(hold * durationScale, token, respectPause);
      }
    } catch (error) {
      if (error.message !== "Animation cancelled") {
        throw error;
      }
    } finally {
      if (localLogoRunId === logoRunId) {
        heroLogoReveal.classList.remove("is-revealing");
        setLogoReveal(100, 0);
      }
    }
  }

  async function playLogoReveal(options = {}, token = runId) {
    const logoSettings = stateLogoSettings[1];
    const delay = Math.max(
      0,
      Number(options.delay ?? logoSettings.revealDelay ?? 0),
    );
    const revealLogoRunId = ++logoRunId;

    syncLogoSettings();
    syncPowerOnVariables(getAnimationSettings(1));
    heroLogoReveal.classList.remove("is-revealing", "is-tube-warming");
    setLogoReveal(0, 0);
    setLogoBlockOpacity(0);

    if (delay > 0) {
      await waitLogoRevealHold(delay, token, options.respectPause);
    }

    if (token !== runId || revealLogoRunId !== logoRunId) {
      return;
    }

    heroLogoReveal.classList.add("is-visible");
    void heroLogoReveal.offsetWidth;

    const stateOneSettings = getAnimationSettings(1);
    let warmupTask = Promise.resolve();
    if (
      stateOneSettings.logoTubeWarmupEnabled &&
      Number(stateOneSettings.logoTubeWarmupDuration || 0) > 0
    ) {
      const warmupLogoRunId = revealLogoRunId;
      const playbackSpeed = Math.max(0.1, stateOneSettings.speed || 1);
      const warmupDuration =
        Math.max(0, Number(stateOneSettings.logoTubeWarmupDuration || 0)) /
        playbackSpeed;
      heroLogoReveal.classList.add("is-tube-warming");
      window.setTimeout(() => {
        if (warmupLogoRunId === logoRunId) {
          heroLogoReveal.classList.remove("is-tube-warming");
        }
      }, warmupDuration);
      warmupTask = waitLogoRevealHold(
        Number(stateOneSettings.logoTubeWarmupDuration || 0),
        token,
        options.respectPause,
      );
    }

    await Promise.all([
      animateLogoBlockOpacity(token, {
        ...options,
        revealRunId: revealLogoRunId,
      }),
      animateLogoReveal(token, { ...options, revealRunId: revealLogoRunId }),
      warmupTask,
    ]);
  }

  function triggerLogoReveal(options = {}) {
    const animationToken = runId;

    void playLogoReveal(options, animationToken).catch((error) => {
      if (error.message !== "Animation cancelled") {
        throw error;
      }
    });
  }

