  function setBuildTitleDots(count = 3) {
    buildTitleCopy.textContent = `Starting build and deployment${".".repeat(count)}`;
  }

  function shuffledIndexes(length) {
    const indexes = Array.from({ length }, (_, index) => index);
    for (let index = indexes.length - 1; index > 0; index -= 1) {
      const swapIndex = Math.floor(Math.random() * (index + 1));
      [indexes[index], indexes[swapIndex]] = [
        indexes[swapIndex],
        indexes[index],
      ];
    }
    return indexes;
  }

  function pulseTerminalBuildElement(element, duration = 240) {
    if (!element) {
      return;
    }

    element.classList.remove("is-terminal-tick");
    void element.offsetWidth;
    element.classList.add("is-terminal-tick");
    window.setTimeout(
      () => element.classList.remove("is-terminal-tick"),
      duration,
    );
  }

  function syncStatusLeaderDots(row) {
    const leader = row.querySelector(".status-leader");
    if (!leader) {
      return [];
    }

    const width =
      leader.offsetWidth || leader.getBoundingClientRect().width || 320;
    const leaderStyles = window.getComputedStyle(leader);
    const reservedStatusGap =
      Number.parseFloat(leaderStyles.paddingRight || "0") || 0;
    const drawableWidth = Math.max(24, width - reservedStatusGap);
    const dotCount = Math.max(16, Math.floor(drawableWidth / 8));
    if (Number(leader.dataset.dotCount) !== dotCount) {
      leader.dataset.dotCount = String(dotCount);
      leader.replaceChildren(
        ...Array.from({ length: dotCount }, () => {
          const dot = document.createElement("span");
          dot.className = "status-leader-dot";
          return dot;
        }),
      );
    }

    return [...leader.querySelectorAll(".status-leader-dot")];
  }

  function resetStatusLeaderDots(row) {
    syncStatusLeaderDots(row).forEach((dot) => dot.classList.remove("is-on"));
  }

  function fillStatusLeaderDotsImmediately(row) {
    syncStatusLeaderDots(row).forEach((dot) => dot.classList.add("is-on"));
  }

  function setStatusLeaderProgress(row, progress) {
    const dots = syncStatusLeaderDots(row);
    const fillTo = Math.min(
      dots.length,
      Math.ceil(dots.length * Math.max(0, Math.min(1, progress))),
    );
    dots.forEach((dot, index) => dot.classList.toggle("is-on", index < fillTo));
  }

  async function fillStatusLeaderDots(
    row,
    token,
    duration = 320,
    options = {},
  ) {
    const dots = syncStatusLeaderDots(row);
    if (!dots.length) {
      return;
    }

    dots.forEach((dot) => dot.classList.remove("is-on"));
    const order = dots.map((_, index) => index);
    const stepCount = Math.max(1, Math.ceil(dots.length / 4));
    const baseStep = Math.max(18, duration / stepCount);
    const cadence = [0.55, 0.95, 0.72, 1.2, 0.68];

    for (let cursor = 0; cursor < order.length; ) {
      if (token !== runId) {
        throw new Error("Animation cancelled");
      }

      const burstSize = cursor % 12 === 0 ? 5 : 4;
      order
        .slice(cursor, cursor + burstSize)
        .forEach((index) => dots[index].classList.add("is-on"));
      cursor += burstSize;

      const delay = Math.min(74, baseStep * cadence[cursor % cadence.length]);
      await wait(delay, token);
    }

    dots.forEach((dot) => dot.classList.add("is-on"));
  }

  function getBuildCompletionOrder() {
    return shuffledIndexes(statusRows.length);
  }

  function resetBuildStatus({ final = false } = {}) {
    buildStatus?.classList.remove("is-terminal-active");
    setBuildTitleDots(3);
    statusRows.forEach((row, index) => {
      row.classList.remove("is-muted", "is-complete", "is-terminal-tick");
      resetStatusLeaderDots(row);
      if (final) {
        row.classList.add("is-complete");
        fillStatusLeaderDotsImmediately(row);
      }
    });
    statusValues.forEach((value, index) => {
      const isOk = final;
      value.textContent = isOk ? "OK" : "In progress";
      value.classList.toggle("status-ok", isOk);
      value.classList.remove("is-switching", "is-terminal-tick");
      value.dataset.trail = "";
    });
  }

  function startBuildDots(token) {
    let dotCount = 0;
    setBuildTitleDots(1);
    const interval = window.setInterval(() => {
      if (token !== runId) {
        window.clearInterval(interval);
        return;
      }

      dotCount = (dotCount % 3) + 1;
      setBuildTitleDots(dotCount);
    }, 180);

    return () => window.clearInterval(interval);
  }

  function makeStatusAsciiFrame(step, steps, width) {
    const size = Math.max(3, Math.min(18, Math.round(width || 7)));
    const safeSteps = Math.max(1, steps - 1);
    const head = Math.round((step / safeSteps) * (size - 1));
    const glyphs = ["░", "▒", "▓", "█"];
    const cells = Array.from({ length: size }, (_, index) => {
      const distance = Math.abs(index - head);
      if (distance === 0) {
        return glyphs[3];
      }
      if (distance === 1) {
        return glyphs[2];
      }
      if (distance === 2) {
        return glyphs[1];
      }
      return glyphs[0];
    });
    return `[${cells.join("")}]`;
  }

  function makeStatusAsciiTrail(step, width) {
    const size = Math.max(3, Math.min(18, Math.round(width || 7)));
    const trailSize = Math.max(3, Math.min(8, Math.ceil(size * 0.5)));
    const pattern = "░▒▓█▓▒";
    return Array.from(
      { length: trailSize },
      (_, index) => pattern[(step + index) % pattern.length],
    ).join("");
  }

  async function switchStatusToOk(value, token) {
    const stateThreeSettings = getAnimationSettings(3);
    const revealDuration = Math.max(
      40,
      Number(stateThreeSettings.statusAsciiSpeed ?? 160),
    );
    const row = value.closest(".status-row");
    if (!row) {
      return;
    }

    setStatusLeaderProgress(row, 1);
    row?.classList.add("is-complete");
    value.classList.add("status-ok", "is-switching");
    value.style.setProperty(
      "--status-switch-duration",
      `${Math.round(revealDuration)}ms`,
    );
    const steps = Math.max(
      2,
      Math.min(6, Math.round(stateThreeSettings.statusOkSteps || 4)),
    );
    const asciiWindow = Math.max(
      3,
      Math.min(18, Math.round(stateThreeSettings.statusAsciiWindow || 7)),
    );
    value.style.setProperty("--status-ok-steps", steps);
    const dots = syncStatusLeaderDots(row);
    const stepDuration = Math.max(28, revealDuration / steps);

    for (let step = 0; step < steps; step += 1) {
      if (token !== runId) {
        throw new Error("Animation cancelled");
      }

      value.textContent = makeStatusAsciiFrame(step, steps, asciiWindow);
      value.dataset.trail = "";
      setStatusLeaderProgress(row, 1);
      dots.forEach((dot, index) => {
        const gradientIndex = (index + step) % 3;
        dot.style.background =
          gradientIndex === 0
            ? "rgba(0, 189, 134, 0.82)"
            : gradientIndex === 1
              ? "rgba(244, 189, 23, 0.66)"
              : "rgba(174, 176, 188, 0.72)";
      });
      await wait(stepDuration, token);
    }

    dots.forEach((dot) => {
      dot.classList.add("is-on");
      dot.style.removeProperty("background");
    });
    value.textContent = "OK";
    value.dataset.trail = "";
    value.classList.remove("is-switching");
    value.style.removeProperty("--status-switch-duration");
    value.style.removeProperty("--status-ok-steps");
  }

